mapper.select:
select t.PORTFOLIO_ID portfolioId, t.IND_ID indId, t.PORTFOLIO_LEVEL portfolioLevel, t.START_DATE startDate, t.END_DATE endDate, case when t.PORTFOLIO_LEVEL='02' then (select PTL_BAG_NAME from RSK_PORTFOLIO_PACKAGE where PTL_BAG_ID=t.PORTFOLIO_ID) else p.PORTFOLIO_NAME end portfolioName, m.IND_NAME indName from RSK_PORTFOLIO_INDICATOR t left join PTL_PORTFOLIO p on t.PORTFOLIO_ID=p.PORTFOLIO_ID left join RSK_ISUP_INDICATOR m on t.IND_ID=m.IND_ID
t.PORTFOLIO_ID = #{portfolioCode}
and t.IND_ID = #{indId}

select count(1) from RSK_PORTFOLIO_INDICATOR 


 	IND_ID = #{indId}


 	and PORTFOLIO_ID in (select PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL where PORTFOLIO_ID= #{portfolioId} )

select count(1) from RSK_PORTFOLIO_INDICATOR 


 	IND_ID = #{indId}


  	and PORTFOLIO_ID in (select DISTINCT(t.PTL_BAG_ID) from RSK_PORTFOLIO_PACKAGE_DTL 
   t where PTL_BAG_ID <> #{portfolioId} and PORTFOLIO_ID 
   in (SELECT PORTFOLIO_ID from  RSK_PORTFOLIO_PACKAGE_DTL where PTL_BAG_ID=#{portfolioId})
    )

select count(1) from RSK_PORTFOLIO_INDICATOR 


 	IND_ID = #{indId}


  	and PORTFOLIO_ID in (SELECT PORTFOLIO_ID from  RSK_PORTFOLIO_PACKAGE_DTL where PTL_BAG_ID=#{portfolioId}
    )
